package io.github.rebrowser.ui;

import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import io.github.rebrowser.browser.*;
import io.github.rebrowser.browser.BrowserModels.*;
import io.github.rebrowser.engine.ViewportPolicy;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.Test;

/** Actual nested presentation/binding models, not Android View/Window/dialog/metric execution. */
public final class NativeWindowModelsTest {
    @Test public void callbackIllegalStateAfterAttemptIsUnknownNotStale(){assertEquals(BrowserToolbar.IntentOutcome.CALLBACK_UNKNOWN,BrowserToolbar.invokeNativeIntent(()->{throw new IllegalStateException("synthetic after handoff");}));}
    @Test public void callbackIllegalArgumentAfterAttemptIsUnknownNotStale(){assertEquals(BrowserToolbar.IntentOutcome.CALLBACK_UNKNOWN,BrowserToolbar.invokeNativeIntent(()->{throw new IllegalArgumentException("synthetic after handoff");}));}
    @Test public void callbackSecurityExceptionAfterAttemptIsUnknownNotUnsubmitted(){assertEquals(BrowserToolbar.IntentOutcome.CALLBACK_UNKNOWN,BrowserToolbar.invokeNativeIntent(()->{throw new SecurityException("synthetic after handoff");}));}
    @Test public void callbackReturnMeansOnlyJavaInvocationReturn(){AtomicInteger calls=new AtomicInteger();assertEquals(BrowserToolbar.IntentOutcome.CALLBACK_RETURNED,BrowserToolbar.invokeNativeIntent(calls::incrementAndGet));assertEquals(1,calls.get());}
    @Test public void absentCallbackIsNotACompletedInvocation(){assertThrows(IllegalArgumentException.class,()->BrowserToolbar.invokeNativeIntent(null));}
    private static final class Catalog {
        final AtomicReference<ComponentGate.SourceState> source=new AtomicReference<>(ComponentGate.SourceState.TRUSTED);
        final ComponentGate gate=new ComponentGate(ProcessRole.MAIN,source::get);final ComponentGate.BusinessPermit permit=gate.requireBusiness();
        final WorkspaceCatalog workspaces=new WorkspaceCatalog(gate);final TabCatalog tabs=new TabCatalog(workspaces);final WorkspaceRef workspace;
        Catalog(){workspace=workspaces.createTemporary(0,permit);tabs.initializeWorkspace(workspace,permit);}
        WorkspacesView view(){return workspaces.snapshot(permit);}TabsView group(){return tabs.snapshot(workspace,permit);}
        BrowserToolbar.Binding binding(){return new BrowserToolbar.Binding(gate,permit,()->{});}
    }
    @Test public void bindingRepeatsCurrentWindowSourceAndIssuingGate(){Catalog c=new Catalog();AtomicInteger checks=new AtomicInteger();BrowserToolbar.Binding binding=new BrowserToolbar.Binding(c.gate,c.permit,checks::incrementAndGet);binding.check();assertEquals(2,checks.get());c.source.set(ComponentGate.SourceState.LOCKED);assertThrows(SecurityException.class,binding::check);}
    @Test public void retiredBindingNeverPublishesIntoNewWindow(){Catalog c=new Catalog();BrowserToolbar.Binding old=c.binding();old.retire();assertThrows(SecurityException.class,old::check);c.binding().check();}
    @Test public void windowGuardCannotReenterBindingOrRetireAndStillReturnSuccess(){Catalog c=new Catalog();AtomicReference<BrowserToolbar.Binding> ref=new AtomicReference<>();BrowserToolbar.Binding binding=new BrowserToolbar.Binding(c.gate,c.permit,()->{if(ref.get()!=null)ref.get().check();});ref.set(binding);assertThrows(SecurityException.class,binding::check);AtomicReference<BrowserToolbar.Binding> other=new AtomicReference<>();BrowserToolbar.Binding retired=new BrowserToolbar.Binding(c.gate,c.permit,()->{if(other.get()!=null)other.get().retire();});other.set(retired);assertThrows(SecurityException.class,retired::check);}
    @Test public void foreignPermitDoesNotBecomeViewAuthority(){Catalog c=new Catalog(),other=new Catalog();assertThrows(SecurityException.class,()->new BrowserToolbar.Binding(c.gate,other.permit,()->{}));}
    @Test public void bindingOwnerThreadIsNotCallerThreadAuthority()throws Exception{Catalog c=new Catalog();BrowserToolbar.Binding binding=c.binding();ExecutorService thread=Executors.newSingleThreadExecutor();try{thread.submit(()->assertThrows(IllegalStateException.class,binding::check)).get(3,TimeUnit.SECONDS);}finally{thread.shutdown();assertTrue(thread.awaitTermination(3,TimeUnit.SECONDS));}}
    @Test public void addressObservationDoesNotOverwriteExplicitEdit(){BrowserToolbar.AddressState state=new BrowserToolbar.AddressState();state.reportDisplay("https://example.test/");state.edit("私人搜索文本");state.reportDisplay("https://other.test/");assertEquals("私人搜索文本",state.visible());state.abandonEdit();assertEquals("https://other.test/",state.visible());}
    @Test public void addressTextBoundedAndUtf16StrictWithoutSearchingOrLoading(){BrowserToolbar.AddressState state=new BrowserToolbar.AddressState();assertThrows(IllegalArgumentException.class,()->state.edit("x".repeat(8193)));assertThrows(IllegalArgumentException.class,()->state.edit("\ud800"));assertThrows(IllegalArgumentException.class,()->state.edit("\udc00"));state.edit("😀");assertEquals("😀",state.visible());}
    @Test public void unbindClearsAddressAndDraftWithoutSaving(){BrowserToolbar.AddressState state=new BrowserToolbar.AddressState();state.reportDisplay("https://example.test/private");state.edit("draft");state.clear();assertEquals("",state.visible());}
    @Test public void selectionOnlyAcceptsCurrentPanelAndReconciledRefs(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.WORKSPACES,null);assertThrows(IllegalArgumentException.class,()->state.toggleWorkspace(c.workspace,state.revision()));state.reconcile(c.view(),null);assertTrue(state.toggleWorkspace(c.workspace,state.revision()));assertEquals(Set.of(c.workspace),state.selectedWorkspaces());assertThrows(IllegalArgumentException.class,()->state.toggleTab(c.group().selected(),state.revision()));}
    @Test public void selectionSnapshotIsImmutableAndStaleClickDoesNotToggleLatest(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.WORKSPACES,null);state.reconcile(c.view(),null);long before=state.revision();state.toggleWorkspace(c.workspace,before);assertThrows(IllegalStateException.class,()->state.toggleWorkspace(c.workspace,before));Set<WorkspaceRef> snapshot=state.selectedWorkspaces();assertThrows(UnsupportedOperationException.class,snapshot::clear);assertTrue(state.clearSelected());assertEquals(1,snapshot.size());assertFalse(state.clearSelected());}
    @Test public void tabSelectionBoundToNativeWorkspaceNotReportedString(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.TABS,c.workspace);state.reconcile(c.view(),c.group());TabRef tab=c.group().selected();assertTrue(state.toggleTab(tab,state.revision()));Catalog other=new Catalog();assertThrows(IllegalArgumentException.class,()->state.toggleTab(other.group().selected(),state.revision()));}
    @Test public void closedTabReconcilesOutWithoutClosingAnotherTab(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.TABS,c.workspace);state.reconcile(c.view(),c.group());TabRef old=c.group().selected();state.toggleTab(old,state.revision());c.tabs.close(old,c.group().revision(),c.permit);state.reconcile(c.view(),c.group());assertTrue(state.selectedTabs().isEmpty());assertNotSame(old,c.group().selected());}
    @Test public void panelChangeClearsSelectionNotDomainCatalog(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.WORKSPACES,null);state.reconcile(c.view(),null);state.toggleWorkspace(c.workspace,state.revision());state.show(OverviewSelection.Panel.TABS,c.workspace);assertTrue(state.selectedWorkspaces().isEmpty());assertEquals(1,c.view().active().size());assertEquals(1,c.group().tabs().size());}
    @Test public void lostWorkspaceClosesSelectionPanelOnly(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.TABS,c.workspace);state.reconcile(c.view(),c.group());c.tabs.retireWorkspace(c.workspace,c.permit);c.workspaces.remove(c.workspace,c.workspaces.workspace(c.workspace,c.permit).revision(),c.permit);state.reconcile(c.view(),null);assertEquals(OverviewSelection.Panel.NONE,state.panel());}
    @Test public void retiredSelectionCannotBeReusedOrResetToAnotherWindow(){OverviewSelection.State state=new OverviewSelection.State();state.retire();state.retire();assertThrows(IllegalStateException.class,state::revision);assertThrows(IllegalStateException.class,()->state.show(OverviewSelection.Panel.WORKSPACES,null));}
    @Test public void workspaceRowsPreservePrimaryPinAndSecondaryShelfLabels(){Catalog c=new Catalog();WorkspacePanel.Rows.validate(c.view());WorkspaceView temporary=c.workspaces.workspace(c.workspace,c.permit);assertTrue(WorkspacePanel.Rows.closeEnabled(temporary));c.workspaces.changeLevel(c.workspace,temporary.revision(),Level.PRIMARY,c.permit);assertFalse(WorkspacePanel.Rows.closeEnabled(c.workspaces.workspace(c.workspace,c.permit)));assertTrue(WorkspacePanel.Rows.description(c.workspaces.workspace(c.workspace,c.permit)).contains("主级"));}
    @Test public void tabRowsRetainPopupDistinctionWithoutOpeningSession(){Catalog c=new Catalog();TabsView before=c.group();c.tabs.addPopup(c.tabs.currentDocument(before.selected(),c.permit),before.revision(),c.permit);TabsView after=c.group();TabPanel.Rows.validate(after);assertTrue(TabPanel.Rows.label(after.tabs().get(1)).startsWith("弹出页"));}
    @Test public void progressStartsAtActualZeroAndNeverUsesTimerAsCompletion(){LoadingProgressView.Model model=new LoadingProgressView.Model();LoadingProgressView.LoadRef load=model.begin(new Object(),new Object());assertEquals(0,model.reportedPercent());assertFalse(model.completed(load));assertTrue(model.reported(load,12));assertEquals(12,model.reportedPercent());assertFalse(model.completed(load));}
    @Test public void progressMonotonicAndBounded(){LoadingProgressView.Model model=new LoadingProgressView.Model();LoadingProgressView.LoadRef load=model.begin(new Object(),new Object());model.reported(load,60);assertFalse(model.reported(load,5));assertEquals(60,model.reportedPercent());assertThrows(IllegalArgumentException.class,()->model.reported(load,101));assertThrows(IllegalArgumentException.class,()->model.reported(load,-1));model.reported(load,100);assertTrue(model.completed(load));}
    @Test public void newLoadAndForeignModelRejectLateProgress(){Object session=new Object(),document=new Object();LoadingProgressView.Model model=new LoadingProgressView.Model(),other=new LoadingProgressView.Model();LoadingProgressView.LoadRef old=model.begin(session,document),current=model.begin(session,new Object());assertFalse(model.reported(old,100));assertFalse(other.reported(current,100));assertEquals(0,model.reportedPercent());assertTrue(model.reported(current,20));}
    @Test public void pageStopDoesNotInvent100OrUnderlyingEnd(){LoadingProgressView.Model model=new LoadingProgressView.Model();LoadingProgressView.LoadRef load=model.begin(new Object(),new Object());model.reported(load,24);assertTrue(model.pageStopped(load));assertEquals(24,model.reportedPercent());assertFalse(model.completed(load));assertFalse(model.reported(load,100));assertFalse(model.pageStopped(load));}
    @Test public void retireProgressMakesOldUiTokenUnusable(){LoadingProgressView.Model model=new LoadingProgressView.Model();LoadingProgressView.LoadRef load=model.begin(new Object(),new Object());model.retire();assertFalse(model.owns(load));assertFalse(model.reported(load,100));assertEquals(0,model.reportedPercent());}
    @Test public void nativeModalUnknownShowHoldsUntilOriginalActualDismiss(){NativeDialogs.Lifecycle state=new NativeDialogs.Lifecycle();NativeDialogs.Token token=state.begin();state.submitting(token);state.submissionUnknown(token);assertTrue(state.hasPending());assertThrows(IllegalStateException.class,state::begin);assertEquals(NativeDialogs.Decision.DISMISSED,state.actualDismissed(token));assertFalse(state.hasPending());}
    @Test public void cancelDecisionIsNotActualDismissOrOwnerAuth(){NativeDialogs.Lifecycle state=new NativeDialogs.Lifecycle();NativeDialogs.Token token=state.begin();state.submitting(token);state.decide(token,NativeDialogs.Decision.CANCELLED);assertTrue(state.hasPending());assertEquals(NativeDialogs.Decision.CANCELLED,state.actualDismissed(token));assertEquals(NativeDialogs.Decision.NONE,state.actualDismissed(token));}
    @Test public void modalFirstDecisionWinsButTextIsNotConsent(){NativeDialogs.Lifecycle state=new NativeDialogs.Lifecycle();NativeDialogs.Token token=state.begin();state.decide(token,NativeDialogs.Decision.TEXT_ENTERED);state.decide(token,NativeDialogs.Decision.CANCELLED);assertEquals(NativeDialogs.Decision.TEXT_ENTERED,state.actualDismissed(token));assertFalse(Arrays.stream(NativeDialogs.Decision.values()).anyMatch(x->x.name().contains("AUTH")));}
    @Test public void unsubmittedSetupFailureCanReleaseWithoutFakeOsCallback(){NativeDialogs.Lifecycle state=new NativeDialogs.Lifecycle();NativeDialogs.Token token=state.begin();assertTrue(state.neverSubmitted(token));assertFalse(state.hasPending());NativeDialogs.Token submitted=state.begin();state.submitting(submitted);assertThrows(IllegalStateException.class,()->state.neverSubmitted(submitted));state.actualDismissed(submitted);}
    @Test public void retiredModalResultsStillNeedActualOriginalDismiss(){NativeDialogs.Lifecycle state=new NativeDialogs.Lifecycle();NativeDialogs.Token token=state.begin();state.submitting(token);state.decide(token,NativeDialogs.Decision.TEXT_ENTERED);state.retireResults();assertTrue(state.hasPending());assertEquals(NativeDialogs.Decision.NONE,state.actualDismissed(token));assertFalse(state.hasPending());assertThrows(IllegalStateException.class,state::begin);}
    @Test public void foreignModalCannotSettleAnotherWindow(){NativeDialogs.Lifecycle a=new NativeDialogs.Lifecycle(),b=new NativeDialogs.Lifecycle();NativeDialogs.Token token=a.begin();assertThrows(SecurityException.class,()->b.actualDismissed(token));assertTrue(a.hasPending());a.actualDismissed(token);}
    @Test public void syncDismissThenShowThrowDoesNotReviveOldModal(){NativeDialogs.Lifecycle state=new NativeDialogs.Lifecycle();NativeDialogs.Token token=state.begin();state.submitting(token);state.actualDismissed(token);NativeDialogs.Token next=state.begin();state.submissionUnknown(token);assertTrue(state.hasPending());assertEquals(NativeDialogs.Decision.DISMISSED,state.actualDismissed(next));}
    @Test public void nativeBackModalWaitsForActualDismissNotCancelDecision(){
        Catalog c=new Catalog();NativeDialogs.Lifecycle modal=new NativeDialogs.Lifecycle();NativeDialogs.Token token=modal.begin();modal.submitting(token);AtomicReference<BackCoordinator.Reporter> reporter=new AtomicReference<>();BackCoordinator back=new BackCoordinator(c.gate,new BackCoordinator.NativeWindow(){public boolean present(BackCoordinator.Layer layer){return layer==BackCoordinator.Layer.MODAL && modal.hasPending();}public void perform(BackCoordinator.Layer layer,BackCoordinator.Reporter owner){reporter.set(owner);modal.decide(token,NativeDialogs.Decision.CANCELLED);}});assertEquals(BackCoordinator.Status.PENDING,back.request(back.presentationRevision(),null).status());assertTrue(back.hasPendingLayer());assertThrows(IllegalStateException.class,()->back.request(back.presentationRevision(),null));modal.actualDismissed(token);assertTrue(reporter.get().reportConsumed());assertFalse(back.hasPendingLayer());
    }
    @Test public void ownWindowInsetsDoNotAccumulateAcrossRepeatedCallbacks(){WindowPresentation.Padding first=WindowPresentation.addOwnedInsets(16,16,16,16,0,24,0,32),again=WindowPresentation.addOwnedInsets(16,16,16,16,0,24,0,32);assertEquals(40,first.top());assertEquals(48,first.bottom());assertEquals(first.top(),again.top());assertEquals(first.bottom(),again.bottom());assertThrows(IllegalArgumentException.class,()->WindowPresentation.addOwnedInsets(-1,0,0,0,0,0,0,0));}
    @Test public void phonePortraitMetricsRemainReadOnlyPolicy(){ViewportPolicy.Snapshot view=ViewportPolicy.observed(1080,2400,0,120,1920,3,false);assertEquals(360,view.widthDp());assertEquals(760,view.heightDp());assertTrue(view.portrait());assertEquals(ViewportPolicy.WidthClass.COMPACT,view.widthClass());assertFalse(view.useSideBySideOverview());}
    @Test public void fullTabletAndNarrowWindowAreDifferentPolicies(){ViewportPolicy.Snapshot full=ViewportPolicy.observed(2560,1600,0,0,2560,2,false),narrow=ViewportPolicy.observed(1000,1600,0,0,2560,2,true);assertTrue(full.useSideBySideOverview());assertTrue(narrow.narrowWindowOnLargeDisplay());assertFalse(narrow.useSideBySideOverview());assertTrue(narrow.panelWidthDp()<=narrow.widthDp());}
    @Test public void tinyWindowPanelNeverExceedsActualWindowWidth(){ViewportPolicy.Snapshot view=ViewportPolicy.observed(100,200,0,0,100,1,true);assertEquals(100,view.panelWidthDp());}
    @Test public void reopenedOverviewNeedsCurrentCatalogNotOldKnownRefs(){Catalog c=new Catalog();OverviewSelection.State state=new OverviewSelection.State();state.show(OverviewSelection.Panel.WORKSPACES,null);state.reconcile(c.view(),null);state.show(OverviewSelection.Panel.NONE,null);state.show(OverviewSelection.Panel.WORKSPACES,null);assertThrows(IllegalArgumentException.class,()->state.toggleWorkspace(c.workspace,state.revision()));state.reconcile(c.view(),null);assertTrue(state.toggleWorkspace(c.workspace,state.revision()));}
    @Test public void selectionRetirementStillFencesAtRevisionExhaustion()throws Exception{OverviewSelection.State state=new OverviewSelection.State();java.lang.reflect.Field revision=OverviewSelection.State.class.getDeclaredField("revision");revision.setAccessible(true);revision.setLong(state,Long.MAX_VALUE);state.retire();assertThrows(IllegalStateException.class,state::revision);}
    @Test public void invalidOrOverflowGeometryIsNotAWebsiteViewportOverride(){assertThrows(IllegalArgumentException.class,()->ViewportPolicy.observed(100,100,100,0,100,1,false));assertThrows(IllegalArgumentException.class,()->ViewportPolicy.observed(100,100,0,0,100,Float.NaN,false));assertThrows(IllegalArgumentException.class,()->ViewportPolicy.observed(Integer.MAX_VALUE,100,0,0,Integer.MAX_VALUE,0.1f,false));}
}
